import json
import yaml

from quilldown_spec import Relationship


def test_load_json_relationship():
    json_data = r"""
    {
      "type": "sample",
      "target": "sample"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = Relationship.load(data)
    assert instance is not None
    assert instance.type == "sample"
    assert instance.target == "sample"


def test_load_yaml_relationship():
    yaml_data = r"""
    type: sample
    target: sample

    """
    data = yaml.load(yaml_data, Loader=yaml.FullLoader)
    instance = Relationship.load(data)
    assert instance is not None
    assert instance.type == "sample"
    assert instance.target == "sample"


def test_roundtrip_json_relationship():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "type": "sample",
      "target": "sample"
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = Relationship.load(original_data)
    saved_data = instance.save()
    reloaded = Relationship.load(saved_data)
    assert reloaded is not None
    assert reloaded.type == "sample"
    assert reloaded.target == "sample"


def test_to_json_relationship():
    """Test that to_json produces valid JSON."""
    json_data = r"""
    {
      "type": "sample",
      "target": "sample"
    }
    """
    data = json.loads(json_data, strict=False)
    instance = Relationship.load(data)
    json_output = instance.to_json()
    assert json_output is not None
    parsed = json.loads(json_output)
    assert isinstance(parsed, dict)


